'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var Float64Array = require( '@stdlib/array/float64' );
var format = require( '@stdlib/string/format' );
var dlasq5 = require( './../lib/dlasq5.js' );
var pkg = require( './../package.json' ).name;
var dlasq4 = require( './../lib/dlasq4.js' );


// VARIABLES //

var options = {
	'dtype': 'float64'
};

var TAU = 0.1;
var SIGMA = 0.0;
var IEEE = true;
var EPS = 2.220446049250313e-16;


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} len - array length
* @returns {Function} benchmark function
*/
function createBenchmark( len ) {
	var DMIN1;
	var DMIN2;
	var DMIN;
	var N0IN;
	var out1 = new Float64Array( 6 );   // [dmin, dmin1, dmin2, dn, dn1, dn2]
	var DN1;
	var DN2;
	var out = new Float64Array( [ 0, 0, 0.25 ] );   // [tau, ttype, g]
	var DN;
	var N0 = floor( ( len / 4 ) - 1 );
	var PP = 0;
	var Z = uniform( len, 0.1, 10.0, options );

	dlasq5( 0, N0, Z, 1, 0, 0, TAU, SIGMA, IEEE, EPS, out1, 1, 0 );

	DMIN = out1[0];
	DMIN1 = out1[1];
	DMIN2 = out1[2];
	DN = out1[3];
	DN1 = out1[4];
	DN2 = out1[5];

	return benchmark;

	function benchmark( b ) {
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			N0IN = N0 + ( i%5 ); // picking a random branch

			dlasq4( 0, N0,	Z, PP, N0IN, DMIN, DMIN1, DMIN2, DN, DN1, DN2, out );

			if ( isnan( out[ i%3 ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();

		if ( isnan( out[ i%3 ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

function main() {
	var len;
	var min;
	var max;
	var f;
	var i;

	min = 1;
	max = 6;

	for ( i = min; i <= max; i++ ) {
		len = pow( 10, i );
		f = createBenchmark( len );
		bench( format( '%s:len=%d', pkg, len ), f );
	}
}

main();
